function createBaseRequestData(): RequestData {
  return { address: "", kind: "", requestedByAdmin: false, wallets: [], suffixes: [] };
}

export const RequestData: MessageFns<RequestData> = {
  encode(message: RequestData, writer: BinaryWriter = new BinaryWriter()): BinaryWriter {
    if (message.address !== "") {
      writer.uint32(10).string(message.address);
    }
    if (message.kind !== "") {
      writer.uint32(18).string(message.kind);
    }
    if (message.requestedByAdmin !== false) {
      writer.uint32(24).bool(message.requestedByAdmin);
    }
    for (const v of message.wallets) {
      writer.uint32(34).string(v!);
    }
    for (const v of message.suffixes) {
      writer.uint32(42).string(v!);
    }
    return writer;
  },

  decode(input: BinaryReader | Uint8Array, length?: number): RequestData {
    const reader = input instanceof BinaryReader ? input : new BinaryReader(input);
    const end = length === undefined ? reader.len : reader.pos + length;
    const message = createBaseRequestData();
    while (reader.pos < end) {
      const tag = reader.uint32();
      switch (tag >>> 3) {
        case 1: {
          if (tag !== 10) {
            break;
          }

          message.address = reader.string();
          continue;
        }
        case 2: {
          if (tag !== 18) {
            break;
          }

          message.kind = reader.string();
          continue;
        }
        case 3: {
          if (tag !== 24) {
            break;
          }

          message.requestedByAdmin = reader.bool();
          continue;
        }
        case 4: {
          if (tag !== 34) {
            break;
          }

          message.wallets.push(reader.string());
          continue;
        }
        case 5: {
          if (tag !== 42) {
            break;
          }

          message.suffixes.push(reader.string());
          continue;
        }
      }
      if ((tag & 7) === 4 || tag === 0) {
        break;
      }
      reader.skip(tag & 7);
    }
    return message;
  },

  fromJSON(object: any): RequestData {
    return {
      address: isSet(object.address) ? globalThis.String(object.address) : "",
      kind: isSet(object.kind) ? globalThis.String(object.kind) : "",
      requestedByAdmin: isSet(object.requestedByAdmin)
        ? globalThis.Boolean(object.requestedByAdmin)
        : isSet(object.requested_by_admin)
        ? globalThis.Boolean(object.requested_by_admin)
        : false,
      wallets: globalThis.Array.isArray(object?.wallets) ? object.wallets.map((e: any) => globalThis.String(e)) : [],
      suffixes: globalThis.Array.isArray(object?.suffixes) ? object.suffixes.map((e: any) => globalThis.String(e)) : [],
    };
  },

  toJSON(message: RequestData): unknown {
    const obj: any = {};
    if (message.address !== "") {
      obj.address = message.address;
    }
    if (message.kind !== "") {
      obj.kind = message.kind;
    }
    if (message.requestedByAdmin !== false) {
      obj.requestedByAdmin = message.requestedByAdmin;
    }
    if (message.wallets?.length) {
      obj.wallets = message.wallets;
    }
    if (message.suffixes?.length) {
      obj.suffixes = message.suffixes;
    }
    return obj;
  },

  create<I extends Exact<DeepPartial<RequestData>, I>>(base?: I): RequestData {
    return RequestData.fromPartial(base ?? ({} as any));
  },
  fromPartial<I extends Exact<DeepPartial<RequestData>, I>>(object: I): RequestData {
    const message = createBaseRequestData();
    message.address = object.address ?? "";
    message.kind = object.kind ?? "";
    message.requestedByAdmin = object.requestedByAdmin ?? false;
    message.wallets = object.wallets?.map((e) => e) || [];
    message.suffixes = object.suffixes?.map((e) => e) || [];
    return message;
  },
};

function createBaseReadRequestsResponse(): ReadRequestsResponse {
  return { wallets: undefined, suffixes: undefined };
}

export const ReadRequestsResponse: MessageFns<ReadRequestsResponse> = {
  encode(message: ReadRequestsResponse, writer: BinaryWriter = new BinaryWriter()): BinaryWriter {
    if (message.wallets !== undefined) {
      RequestData.encode(message.wallets, writer.uint32(10).fork()).join();
    }
    if (message.suffixes !== undefined) {
      RequestData.encode(message.suffixes, writer.uint32(18).fork()).join();
    }
    return writer;
  },

  decode(input: BinaryReader | Uint8Array, length?: number): ReadRequestsResponse {
    const reader = input instanceof BinaryReader ? input : new BinaryReader(input);
    const end = length === undefined ? reader.len : reader.pos + length;
    const message = createBaseReadRequestsResponse();
    while (reader.pos < end) {
      const tag = reader.uint32();
      switch (tag >>> 3) {
        case 1: {
          if (tag !== 10) {
            break;
          }

          message.wallets = RequestData.decode(reader, reader.uint32());
          continue;
        }
        case 2: {
          if (tag !== 18) {
            break;
          }

          message.suffixes = RequestData.decode(reader, reader.uint32());
          continue;
        }
      }
      if ((tag & 7) === 4 || tag === 0) {
        break;
      }
      reader.skip(tag & 7);
    }
    return message;
  },

  fromJSON(object: any): ReadRequestsResponse {
    return {
      wallets: isSet(object.wallets) ? RequestData.fromJSON(object.wallets) : undefined,
      suffixes: isSet(object.suffixes) ? RequestData.fromJSON(object.suffixes) : undefined,
    };
  },

  toJSON(message: ReadRequestsResponse): unknown {
    const obj: any = {};
    if (message.wallets !== undefined) {
      obj.wallets = RequestData.toJSON(message.wallets);
    }
    if (message.suffixes !== undefined) {
      obj.suffixes = RequestData.toJSON(message.suffixes);
    }
    return obj;
  },

  create<I extends Exact<DeepPartial<ReadRequestsResponse>, I>>(base?: I): ReadRequestsResponse {
    return ReadRequestsResponse.fromPartial(base ?? ({} as any));
  },
  fromPartial<I extends Exact<DeepPartial<ReadRequestsResponse>, I>>(object: I): ReadRequestsResponse {
    const message = createBaseReadRequestsResponse();
    message.wallets = (object.wallets !== undefined && object.wallets !== null)
      ? RequestData.fromPartial(object.wallets)
      : undefined;
    message.suffixes = (object.suffixes !== undefined && object.suffixes !== null)
      ? RequestData.fromPartial(object.suffixes)
      : undefined;
    return message;
  },
};

